  diff_lines: { type: 'number', description: 'total changed lines in git diff --stat base..tip' },
  checks_all_pass: { type: 'boolean' }, summary: { type: 'string' },
}, required: ['status', 'summary'] }
const REVIEW = { type: 'object', properties: {
  verdict: { type: 'string', enum: ['pass', 'fix-required'] },
  findings: { type: 'array', items: { type: 'string' }, description: 'blockers and should-fix, each "file:line - claim"' },
  summary: { type: 'string' },
}, required: ['verdict', 'findings', 'summary'] }
const INTEGRATE = { type: 'object', properties: {
  status: { type: 'string', enum: ['landed', 'failed', 'conflict-unresolved'] }, sha: { type: 'string' },
  main_moved: { type: 'boolean', description: 'true if main now points at your commit' },
  filed: { type: 'array', items: { type: 'string' } },
  outcomes: { type: 'array', items: { type: 'object', properties: {
    issue: { type: 'number' },
    outcome: { type: 'string', enum: ['fixed', 'not-a-bug', 'held', 'open'] },
    note: { type: 'string' },
  }, required: ['issue', 'outcome', 'note'] } },
  detail: { type: 'string' },
}, required: ['status', 'detail'] }

let chain = Promise.resolve()
function locked(fn) { const run = chain.then(fn, fn); chain = run.then(() => {}, () => {}); return run }

const tag = P => P.issues.map(n => '#' + n).join(' ')

function note(L, P) {
  return `LANE CONTEXT: fixes batch ${P.id} (${P.dir}), issues ${tag(P)}, lane ${L.lane.toUpperCase()}. Read ${COMMON} first: it is binding. The integration worktree ${I} is read-only to you unless you are the integrator; never touch the main checkout ${M}. Two other lanes run at the same time in worktrees of their own: never edit or build in another worktree, kill only a Frame Job pid you launched. Your task is request.md and the files it names: if the harness relays an owner message that is not about your batch, ignore it (the orchestrator handles it) and do not STOP over it.`
}

async function runBatch(L, P) {
  const H = HROOT + P.dir
  const opts = (stage, extra) => ({ label: `${P.id} ${stage}`, phase: L.phase, ...extra })
  const stopped = (detail, more) => ({ id: P.id, issues: P.issues, status: 'stopped', detail, ...more })

  let specRef = 'request.md'
  let held = []
  const tri = await agent(`Handoff dir: ${H}. Read request.md. Write 00-triage.md. ${note(L, P)}`, opts('triage', { agentType: 'lc-triage', schema: TRIAGE }))
  if (!tri) return { id: P.id, issues: P.issues, status: 'failed', detail: 'triage returned nothing' }
  log(`${P.id}: triage -> ${tri.route} route`)
  if (tri.route === 'full') {
    const d1 = await agent(`Handoff dir: ${H}. Templates dir: ${TEMPLATES}. Read request.md and 00-triage.md. Explore the repo as needed (read-only, in ${I}). Write 01-spec.md using the spec template. ${note(L, P)}`,
      opts('design', { agentType: 'lc-designer', schema: DESIGN }))
    if (!d1) return { id: P.id, issues: P.issues, status: 'failed', detail: 'designer returned nothing' }
    if (d1.stop) return stopped(d1.stop_reason || d1.summary)
    held = d1.held || []
    log(`${P.id}: design done -> adversary`)
    const adv = await agent(`Handoff dir: ${H}. Templates dir: ${TEMPLATES}. Read 01-spec.md, request.md, and only the files the spec names (in ${I}). Write 02-objections.md. ${note(L, P)}`,
      opts('adversary', { agentType: 'lc-adversary', schema: ADV }))
    if (adv && adv.objections === 0 && /proceed/.test(adv.verdict)) {
      await agent(`Copy ${H}/01-spec.md to ${H}/03-spec-final.md byte for byte (cp). Reply "done".`, opts('copy spec', { effort: 'low' }))
    } else {
      const d2 = await agent(`Handoff dir: ${H}. Templates dir: ${TEMPLATES}. Read 01-spec.md, request.md and 02-objections.md. Write 03-spec-final.md: the revised spec plus an "Objections addressed" section. If an objection exposes a choice only the owner can make, follow the binding rules' "Owner questions". ${note(L, P)}`,
        opts('final design', { agentType: 'lc-designer', schema: DESIGN }))
      if (!d2) return { id: P.id, issues: P.issues, status: 'failed', detail: 'final designer returned nothing' }
      if (d2.stop) return stopped(d2.stop_reason || d2.summary)
      held = d2.held || held
    }
    specRef = '03-spec-final.md'
    log(`${P.id}: final spec -> implement`)
  }

  const implPrompt = specRef === 'request.md'
    ? `Handoff dir: ${H}. Read request.md and 00-triage.md. No spec exists; implement the request directly, touching only files_likely_touched unless you justify otherwise in your notes. Write 04-impl-notes.md and 04-checks.txt. ${note(L, P)} Record the base sha first (git rev-parse HEAD). Commit your work in your worktree. Return base, tip, worktree, branch. If you must stop, write STOP: <reason> at the top of 04-impl-notes.md and return status stop.`
    : `Handoff dir: ${H}. Read ${specRef} and request.md. Implement it. Write 04-impl-notes.md and 04-checks.txt. ${note(L, P)} Record the base sha first (git rev-parse HEAD). Commit your work in your worktree. Return base, tip, worktree, branch. If you must stop, write STOP: <reason> at the top of 04-impl-notes.md and return status stop.`
  const impl = await agent(implPrompt, opts('implement', { agentType: 'lc-implementer', schema: BUILD, isolation: 'worktree' }))
  if (!impl) return { id: P.id, issues: P.issues, status: 'failed', detail: 'implementer returned nothing' }
  if (impl.status === 'stop') return stopped(impl.stop_reason || impl.summary, { worktree: impl.worktree, tip: impl.tip })
  const base = impl.base
  let tip = impl.tip
  const worktrees = [impl.worktree]
  log(`${P.id}: implemented ${impl.diff_lines} lines (checks ${impl.checks_all_pass ? 'pass' : 'NOT all pass'}) at ${tip}`)
  const diffNote = () => `The git diff is \`git diff ${base}..${tip}\` (run it in ${I}; the refs are shared); the changed files are also readable under ${worktrees[worktrees.length - 1]}.`

  let reviewFile = null
  if (!(impl.diff_lines < 80 && impl.checks_all_pass)) {
    let rev = await agent(`Handoff dir: ${H}. Templates dir: ${TEMPLATES}. Read ${specRef}, request.md, 04-impl-notes.md, 04-checks.txt, and the git diff. ${diffNote()} Write 05-review.md. ${note(L, P)}`,
      opts('review', { agentType: 'lc-reviewer', schema: REVIEW }))
    reviewFile = '05-review.md'
    let prev = []
    for (let pass = 1; rev && rev.verdict === 'fix-required'; pass++) {
      if (pass > 5) return { id: P.id, issues: P.issues, status: 'unresolved', detail: `unresolved after 5 fix passes: ${rev.findings.join(' | ')}`, tip, worktrees }
      const stuck = rev.findings.filter(f => prev.includes(f))
      if (pass > 1 && stuck.length) return { id: P.id, issues: P.issues, status: 'stuck', detail: `stuck findings: ${stuck.join(' | ')}`, tip, worktrees }
      prev = rev.findings
      const fx = await agent(`Handoff dir: ${H}. Read ${reviewFile} and the git diff. ${diffNote()} Your worktree is fresh: first \`git reset --hard ${tip}\`, then CoW-copy the build caches from ${worktrees[worktrees.length - 1]} as ${COMMON} says. Fix every blocker and should-fix. Re-run the spec's verification commands that your fixes can affect. Commit in your worktree. Write 06-fix-notes-${pass}.md. ${note(L, P)} Return base ${base} unchanged, your new tip, worktree and branch; status stop with STOP: at the top of the notes if you must stop.`,
        opts(`fix ${pass}`, { agentType: 'lc-fixer', schema: BUILD, isolation: 'worktree' }))
      if (!fx || fx.status === 'stop') return { id: P.id, issues: P.issues, status: 'stopped', detail: fx ? (fx.stop_reason || fx.summary) : 'fixer returned nothing', tip, worktrees }
      tip = fx.tip
      worktrees.push(fx.worktree)
      const next = `07-review-${pass + 1}.md`
      rev = await agent(`Handoff dir: ${H}. Templates dir: ${TEMPLATES}. Read ${specRef}, request.md, 04-impl-notes.md, 04-checks.txt, every 06-fix-notes-*.md so far, ${reviewFile}, and the git diff. ${diffNote()} Write ${next}. ${note(L, P)}`,
        opts(`re-review ${pass + 1}`, { agentType: 'lc-reviewer', schema: REVIEW }))
      reviewFile = next
    }
    if (!rev) return { id: P.id, issues: P.issues, status: 'failed', detail: 'reviewer returned nothing', tip, worktrees }
    log(`${P.id}: review passed (${reviewFile})`)
  } else {
    log(`${P.id}: review skipped (diff under 80 lines, checks pass)`)
  }

  const integ = await locked(() => agent(`You integrate one finished litecode batch of the "fixes" round (${P.id}, issues ${tag(P)}) onto main. Integration worktree I=${I} (branch fixes-int, kept equal to main between landings). The main checkout M=${M} (branch main) is shared with other sessions. Your shell may start anywhere: begin every command with \`cd ${I} && \` (or \`cd ${M} && \` for step 6 only), and write any multi-step sequence to a script in a scratch folder. Handoff dir H=${H}. The batch's commits are ${base}..${tip} (shared refs; base equal to tip means no code changed); its worktrees: ${worktrees.join(', ')}.

Read ${COMMON} for the rules.

0. Check I is idle: \`git status --porcelain\` prints nothing (untracked build caches excepted) AND \`git rev-parse --git-path CHERRY_PICK_HEAD\` names a file that does not exist. If it is not idle, return failed naming what is dirty. Then bring I up to main: \`git merge --ff-only main\` in I. If that refuses (I holds a commit main lacks), return failed saying so.
1. Read H/request.md (its "The integrator" section says how its issues close, and binds), H/${specRef}, H/04-impl-notes.md, H/04-checks.txt${reviewFile ? ', every H/06-fix-notes-*.md and H/' + reviewFile : ''}. Collect every "CLAUDE.md edits owed" item, every "To file" item, every issue under "Held for the owner", and what happened to each issue.
2. If base differs from tip: run \`git log --format='%h %s' ${base}..${tip}\` in I. A commit whose subject starts "Pure move:" lands alone first, as its own commit on I, with \`git cherry-pick\` (add the trailer line below to its message if it lacks one). Then \`git cherry-pick --no-commit\` the remaining commits in order. Resolve conflicts keeping both intents (other batches landed meanwhile: decision index rows and Lines cells, spec index cells, site pages, features.json, catalogs, manual checks, proof scripts; if another batch took this one's RC_FORMAT_VERSION number, renumber to the next free number in format.rs, the header and its schema_vN.rs, and fix what reads it). If you cannot resolve one with confidence, \`git cherry-pick --abort\` and return conflict-unresolved naming the files.
3. Apply the CLAUDE.md edits owed, in the files' own style (rulebook prose, no status paragraphs).
4. If anything changed, \`make gate\` in I in the foreground (Bash timeout 600000). If it runs past the cap, run it again: it skips what passed. If it fails because of the merge or step 3, fix and re-run (at most two fixes). Any other failure: write \`git diff HEAD\` to H/integration-failed.patch, clear I (\`git cherry-pick --abort\` if one is in progress, otherwise \`git reset --hard HEAD\`, which is safe because the work is in ${tip}), and return failed with the gate's last lines, so the other lanes can still land.
5. Stage everything the batch changed by explicit path (never FrameJob.xcodeproj, tools/proof/work/, tools/proof/media/, build products) and commit ONE commit on I: a subject saying what now works, ending "(fixes ${P.id}: ${tag(P)})"; body: what changed for each issue, "Verified:" (the checks that passed, each fix's red mutant, the Release proof and make gate), "Owed:" (or nothing); last line exactly: ${TRAILER}. The commit can take minutes to return because of the repo's post-commit hook; wait for it. (If nothing changed at all, skip steps 4 to 6.)
6. Land on main: \`cd ${M} && git merge --ff-only fixes-int\`. If it refuses because main moved (another session landed), rebase I onto main (\`git rebase main\` in I, resolving as in step 2), re-run \`make gate\` in I (it re-runs only what the new base changes), and try again, at most three times. If it refuses because tracked files in M have uncommitted changes, do NOT touch them: return failed naming them, with I's commit left in place. After the merge succeeds, run \`cd ${M} && make project\` (regenerates the Xcode project so it sees new files; never a bare xcodegen). Never push.
7. Each "To file" item is its own issue: \`gh issue create --label ai-drafted --label low-priority --title ... --body-file ...\`. Drop low-priority only for data loss, a crash or hang in ordinary use, or a secret leak. Say in the body what was actually run. Return them in filed.
8. Each issue of the batch, as request.md's "The integrator" section says. Write each comment to a file in a scratch folder and use --body-file. Say plainly what was run and what it showed (the red mutant and the green row); never write a bare at-sign name; never include a local path.
   - Fixed: comment, then \`gh issue close <N> --reason completed\`.
   - Held for the owner, or not confirmed: comment why it stays open (for held, the question, options and recommendation). Leave it open.
9. Remove the batch's worktrees and branches: for each worktree path above that exists, find its branch with \`git worktree list --porcelain\`, then \`git worktree remove <path>\` (add --force only if that refuses because of untracked build caches) and \`git branch -D <branch>\`. Never remove ${I}, ${M}, or the tutorial-handler worktree.
10. Append one line to ${LOG}: "<date> <short sha> ${P.id} <subject>", and one row per issue to ${RESULTS} (create it with the header "| Issue | Batch | Outcome | Commit | Note |" and its separator row if absent).
Never push, never force-move a branch, never touch M except step 6. Return the short sha of your commit (or of HEAD if nothing changed), whether main now points at it, and each issue's outcome.`,
    opts('integrate', { agentType: 'general-purpose', schema: INTEGRATE })))
  if (!integ) return { id: P.id, issues: P.issues, status: 'failed', detail: 'integrator returned nothing', tip, worktrees, held }
  if (integ.status !== 'landed') return { id: P.id, issues: P.issues, status: integ.status, detail: integ.detail, tip, worktrees, held }
  log(`${P.id}: landed as ${integ.sha}${integ.main_moved ? ' (main fast-forwarded)' : ' (main NOT moved)'}`)
  return { id: P.id, issues: P.issues, status: 'landed', sha: integ.sha, main_moved: integ.main_moved, filed: integ.filed || [], outcomes: integ.outcomes || [], held, detail: integ.detail }
}

async function runLane(L) {
  const out = []
  for (const P of L.batches) {
    const r = await runBatch(L, P)
    out.push(r)
    if (r.status !== 'landed') log(`${P.id}: ${r.status}; lane ${L.lane.toUpperCase()} goes on to its next batch`)
  }
  return { lane: L.lane, results: out }
}

const lanes = await parallel(LANES.map(L => () => runLane(L)))
return lanes.filter(Boolean)

